pub fn names(row: &[(&'static str, Flag)]) -> Vec<&'static str> {
    row.iter().map(|(f, _)| *f).collect()
}

pub fn kind(verb: &str, flag: &str) -> Option<Flag> {
    HOME.iter().find(|(v, _)| *v == verb).and_then(|(_, fl)| fl.iter().find(|(f, _)| *f == flag)).map(|(_, k)| *k)
}
